using namespace std;

int main() {
    string s;
    cin >> s;

    long long leftQ = 0;
    long long rightQ = count(s.begin(), s.end(), 'Q');
    long long result = 0;

    for (char ch : s) {
        if (ch == 'Q') {
            ++leftQ;
            --rightQ;
        } else if (ch == 'A') {
            result += leftQ * rightQ;
        }
    }

    cout << result;
    return 0;
}

